598	func (req CreateAuthorizationRequest) validatePresent() error {
599		missing := []string{}
600		if strings.TrimSpace(req.Operator) == "" {
601			missing = append(missing, "operator")
602		}
603		if strings.TrimSpace(req.Reason) == "" {
604			missing = append(missing, "reason")
605		}
606		if strings.TrimSpace(req.RequestID) == "" {
607			missing = append(missing, "request_id")
608		}
609		if strings.TrimSpace(req.AuthID) == "" {
610			missing = append(missing, "auth_id")
611		}
612		if strings.TrimSpace(req.ItemID) == "" {
613			missing = append(missing, "item_id")
614		}
615		if strings.TrimSpace(req.TrusteeID) == "" {
616			missing = append(missing, "trustee_id")
617		}
618		if strings.TrimSpace(req.ToID) == "" {
619			missing = append(missing, "to_id")
620		}
621		if strings.TrimSpace(req.ExpectedOwner) == "" {
622			missing = append(missing, "expected_owner")
623		}
624		if req.ExpectedVer <= 0 {
625			missing = append(missing, "expected_version")
626		}
627		if req.ExpiresAt.IsZero() {
628			missing = append(missing, "expires_at")
629		}
630		if len(missing) > 0 {
631			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
632		}
633		if req.Price < 0 {
634			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
635		}
636		return nil
637	}
638	
639	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
640		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
641		// 仍可回放；改价则按请求号冲突拒绝。
642		b, _ := json.Marshal(struct {
643			Kind          string `json:"kind"`
644			AuthID        string `json:"auth_id"`
645			ItemID        string `json:"item_id"`
646			TrusteeID     string `json:"trustee_id"`
647			ToID          string `json:"to_id"`
648			ExpectedOwner string `json:"expected_owner"`
649			ExpectedVer   int64  `json:"expected_version"`
650			ExpiresAt     string `json:"expires_at"`
651			Price         int64  `json:"price,omitempty"`
652			Reason        string `json:"reason"`
653		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
654			req.ExpectedOwner, req.ExpectedVer,
655			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
656		return string(b)
657	}
658	
659	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
660	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
661	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
662	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
663	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
664	//
665	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
666	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
667	// 参数错误与引用不存在不占用请求号。
668	//
669	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
670	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
671	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
672	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
673	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
674	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
675	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
676	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
677	// 错误（首次重提不标回放），状态已满足请求则正常创建。
678	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
679		if err := req.validatePresent(); err != nil {
680			return CreateAuthorizationResult{}, err
681		}
682		r.mu.Lock()
683		defer r.mu.Unlock()
684		if err := r.checkOpen(); err != nil {
685			return CreateAuthorizationResult{}, err
686		}
687	
688		now := r.now()
689		key := requestKey(req.Operator, req.RequestID)
690		sig := createAuthzParamsSig(req)
691		if prev, ok := r.state.Requests[key]; ok {
692			return r.replayCreateAuthz(prev, sig)
693		}
694	
695		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
696			if !isValidationErr(bizErr) {
697				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
698				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
699				r.state.Requests[key] = request{
700					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
701					Params: sig, Rejected: true, Reason: errCode(bizErr),
702					AuthID: req.AuthID, ItemID: req.ItemID,
703				}
704				if err := r.commit(); err != nil {
705					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
706					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
707					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
708					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
709					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
710					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
711					// 为零、不标回放、结果中业务错误为空，error 保留实际
712					// 写入错误。
713					delete(r.state.Requests, key)
714					return CreateAuthorizationResult{}, err
715				}
716			}
717			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
718		}
719	
720		h := r.state.Holdings[req.ItemID]
721		a := authzRec{
722			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
723			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
724			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
725		}
726		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
727		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
728		// 一次成功保存都会把这份未保存的授权带进登记册。
729		prevAuthSeq := r.state.NextAuthSeq
730		prevEvents := len(r.state.AuthEvents)
731		r.state.Authzs[req.AuthID] = a
732		authSeq := prevAuthSeq + 1
733		r.state.NextAuthSeq = authSeq
734		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
735			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
736			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
737			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
738		})
739		r.state.Requests[key] = request{
740			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
741			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
742		}
743		if err := r.commit(); err != nil {
744			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
745			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
746			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
747			if _, ok := r.state.Requests[key]; ok {
748				delete(r.state.Requests, key)
749				delete(r.state.Authzs, req.AuthID)
750				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
751				r.state.NextAuthSeq = prevAuthSeq
752			}
753			return CreateAuthorizationResult{}, err
754		}
755		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
756	}
757	
758	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
759		h, ok := r.state.Holdings[req.ItemID]
760		if !ok {
761			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
762				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
763			}
764			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
765		}
766		op, ok := r.state.Accounts[req.Operator]
767		if !ok {
768			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
769		}
770		trustee, ok := r.state.Accounts[req.TrusteeID]
771		if !ok {
772			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
773		}
774		to, ok := r.state.Accounts[req.ToID]
775		if !ok {
776			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
777		}
778		if req.TrusteeID == req.Operator {
779			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
780		}
781		if req.ToID == req.Operator {
782			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
783		}
784		if !op.Active {
785			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
786		}
787		if !trustee.Active {
788			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
789		}
790		if !to.Active {
791			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
792		}
793		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
794		if _, exists := r.state.Authzs[req.AuthID]; exists {
795			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
796		}
797		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
798		if !req.ExpiresAt.After(now) {
799			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
800				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
801		}
802		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
803			req.Operator != h.OwnerID {
804			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
805				ErrConflict, req.ItemID, h.OwnerID, h.Version)
806		}
807		return nil
808	}
809	
810	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
811		if prev.Kind != "auth_create" || prev.Params != sig {
812			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
813				ErrRequestConflict, prev.Operator, prev.RequestID)
814		}
815		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
816			Status: AuthActive, Replayed: true}
817		if prev.Rejected {
818			res.Err = codeErr(prev.Reason)
819			return res, res.Err
820		}
821		return res, nil
822	}
823	
824	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
825		b, _ := json.Marshal(struct {
826			Kind   string `json:"kind"`
827			AuthID string `json:"auth_id"`
828			Reason string `json:"reason"`
829		}{"auth_revoke", req.AuthID, req.Reason})
830		return string(b)
831	}
832	
833	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
834	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
835	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
836	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
837		missing := []string{}
838		if strings.TrimSpace(req.Operator) == "" {
839			missing = append(missing, "operator")
840		}
841		if strings.TrimSpace(req.Reason) == "" {
842			missing = append(missing, "reason")
843		}
844		if strings.TrimSpace(req.RequestID) == "" {
845			missing = append(missing, "request_id")
846		}
847		if strings.TrimSpace(req.AuthID) == "" {
848			missing = append(missing, "auth_id")
849		}
850		if len(missing) > 0 {
851			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
852				ErrInvalidArgument, strings.Join(missing, ", "))
853		}
854		r.mu.Lock()
855		defer r.mu.Unlock()
856		if err := r.checkOpen(); err != nil {
857			return RevokeAuthorizationResult{}, err
858		}
859	
860		now := r.now()
861		key := requestKey(req.Operator, req.RequestID)
862		sig := revokeAuthzParamsSig(req)
863		if prev, ok := r.state.Requests[key]; ok {
864			return r.replayRevokeAuthz(prev, sig)
865		}
866	
867		a, ok := r.state.Authzs[req.AuthID]
868		if !ok {
869			// 引用不存在不占用请求号。
870			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
871			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
872		}
873		if a.GranterID != req.Operator {
874			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
875				ErrForbidden, a.GranterID, req.AuthID)
876			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
877			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
878		}
879		switch authzCurrentStatus(a, now) {
880		case AuthUsed:
881			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
882			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
883			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
884		case AuthRevoked:
885			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
886			// 相同请求重放回放同一结果。
887			r.state.Requests[key] = request{
888				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
889				Params: sig, AuthID: req.AuthID,
890			}
891			if err := r.commit(); err != nil {
892				return RevokeAuthorizationResult{}, err
893			}
894			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
895		}
896	
897		from := AuthActive
898		if authzCurrentStatus(a, now) == AuthExpired {
899			from = AuthExpired
900		}
901		a.Status = "revoked"
902		a.RevokedAt = now
903		r.state.Authzs[req.AuthID] = a
904		authSeq := r.state.NextAuthSeq + 1
905		r.state.NextAuthSeq = authSeq
906		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
907			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
908			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
909			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
910		})
911		r.state.Requests[key] = request{
912			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
913			Params: sig, AuthID: req.AuthID,
914		}
915		if err := r.commit(); err != nil {
916			return RevokeAuthorizationResult{}, err
917		}
918		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
919	}
920	
921	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
922	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
923		r.state.Requests[key] = request{
924			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
925			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
926		}
927		_ = r.commit()
928	}
929	
930	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
931		if prev.Kind != "auth_revoke" || prev.Params != sig {
932			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
933				ErrRequestConflict, prev.Operator, prev.RequestID)
934		}
935		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
936		if prev.Rejected {
937			res.Err = codeErr(prev.Reason)
938			res.Status = ""
939			return res, res.Err
940		}
941		return res, nil
942	}
943	
944	func proxyTransferParamsSig(req ProxyTransferRequest) string {
945		b, _ := json.Marshal(struct {
946			Kind   string `json:"kind"`
947			AuthID string `json:"auth_id"`
948			Reason string `json:"reason"`
949		}{"proxy_transfer", req.AuthID, req.Reason})
950		return string(b)
951	}
952	
953	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
954	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
955	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
956	// 操作者记为实际受托账户并可通过授权编号追溯。
957	//
958	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
959	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
960	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
961	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
962	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
963	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
964	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
965		missing := []string{}
966		if strings.TrimSpace(req.Operator) == "" {
967			missing = append(missing, "operator")
968		}
969		if strings.TrimSpace(req.Reason) == "" {
970			missing = append(missing, "reason")
971		}
972		if strings.TrimSpace(req.RequestID) == "" {
973			missing = append(missing, "request_id")
974		}
975		if strings.TrimSpace(req.AuthID) == "" {
976			missing = append(missing, "auth_id")
977		}
978		if len(missing) > 0 {
979			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
980				ErrInvalidArgument, strings.Join(missing, ", "))
981		}
982		r.mu.Lock()
983		defer r.mu.Unlock()
984		if err := r.checkOpen(); err != nil {
985			return ProxyTransferResult{}, err
986		}
987	
988		now := r.now()
989		key := requestKey(req.Operator, req.RequestID)
990		sig := proxyTransferParamsSig(req)
991		if prev, ok := r.state.Requests[key]; ok {
992			return r.replayProxyTransfer(prev, sig)
993		}
994	
995		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
996			if !isValidationErr(bizErr) {
997				r.state.Requests[key] = request{
998					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
999					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1000				}
1001				_ = r.commit()
1002			}
1003			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1004		}
1005	
1006		a := r.state.Authzs[req.AuthID]
1007		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1008		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1009		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1010		// 追溯。
1011		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1012		a.Status = "used"
1013		a.UsedTxSeq = out.seq
1014		a.UsedAt = now
1015		r.state.Authzs[a.ID] = a
1016		authSeq := r.state.NextAuthSeq + 1
1017		r.state.NextAuthSeq = authSeq
1018		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1019			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1020			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1021			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1022		})
1023		r.state.Requests[key] = request{
1024			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1025			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1026			Version: out.toVer(), TxSeq: out.seq,
1027		}
1028		if err := r.commit(); err != nil {
1029			return ProxyTransferResult{}, err
1030		}
1031		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1032			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1033			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1034			Remainder: out.royalty.Remainder}, nil
1035	}
1036	
1037	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1038		a, ok := r.state.Authzs[req.AuthID]
1039		if !ok {
1040			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1041		}
1042		op, ok := r.state.Accounts[req.Operator]
1043		if !ok {
1044			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1045		}
1046		granter, gOk := r.state.Accounts[a.GranterID]
1047		to, tOk := r.state.Accounts[a.ToID]
1048		if req.Operator != a.TrusteeID {
1049			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1050				ErrForbidden, req.Operator, req.AuthID)
1051		}
1052		if !gOk {
1053			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1054		}
1055		if !tOk {
1056			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1057		}
1058		if !op.Active {
1059			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1060		}
1061		if !granter.Active {
1062			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1063		}
1064		if !to.Active {
1065			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1066		}
1067		switch authzCurrentStatus(a, now) {
1068		case AuthRevoked:
1069			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1070		case AuthExpired:
1071			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1072		case AuthUsed:
1073			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1074		}
1075		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1076		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1077		h, ok := r.state.Holdings[a.ItemID]
1078		if !ok {
1079			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1080		}
1081		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1082			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1083				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1084		}
1085		return nil
1086	}
1087	
1088	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1089		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1090			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1091				ErrRequestConflict, prev.Operator, prev.RequestID)
1092		}
1093		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1094			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1095		if prev.Rejected {
1096			res.Err = codeErr(prev.Reason)
1097			return res, res.Err
1098		}
1099		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1100		// 原价款与应付明细，不重复计入。
1101		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1102		return res, nil
1103	}
