package registry

import (
	"errors"
	"testing"
	"time"
)

// 临时验证：撤销授权的两类业务拒绝在保存失败时的行为。
func TestTmpRevokeRejectSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}

	// 非授权人撤销：ErrForbidden，保存失败。
	req := RevokeAuthorizationRequest{Operator: "bob", Reason: "越权", RequestID: "rev-1", AuthID: "a1"}
	blockBatchSave(t, r)
	res, err := r.RevokeAuthorization(req)
	assertSaveFailureError(t, err)
	if res.AuthID != "" || res.Status != "" || res.Replayed || res.Err != nil {
		t.Fatalf("保存失败必须返回空结果: %+v", res)
	}
	if _, ok := r.state.Requests[requestKey("bob", "rev-1")]; ok {
		t.Fatal("未保存的拒绝不应占用请求号")
	}
	// 授权内容保持操作前状态。
	a, err := r.GetAuthorization("a1")
	if err != nil || a.Status != AuthActive {
		t.Fatalf("授权不应被改变: %+v, %v", a, err)
	}

	// 保存未恢复再次提交：仍返回保存错误。
	res, err = r.RevokeAuthorization(req)
	assertSaveFailureError(t, err)
	if res.AuthID != "" || res.Err != nil {
		t.Fatalf("保存失败必须返回空结果: %+v", res)
	}

	// 恢复后重提：保存拒绝成功，返回 ErrForbidden，不标回放。
	restoreBatchSave(t, r)
	res, err = r.RevokeAuthorization(req)
	if !errors.Is(err, ErrForbidden) || res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrForbidden) {
		t.Fatalf("重提应在保存后返回 ErrForbidden: %+v, %v", res, err)
	}
	// 再次相同提交：回放。
	res, err = r.RevokeAuthorization(req)
	if !errors.Is(err, ErrForbidden) || !res.Replayed || res.AuthID != "a1" {
		t.Fatalf("保存后的重提应回放: %+v, %v", res, err)
	}

	// 已使用授权的撤销拒绝：ErrAuthorizationUsed，保存失败同样处理。
	if _, err := r.ProxyTransfer(ProxyTransferRequest{Operator: "bob", Reason: "代转", RequestID: "pt-1", AuthID: "a1"}); err != nil {
		t.Fatal(err)
	}
	req2 := RevokeAuthorizationRequest{Operator: "alice", Reason: "撤销", RequestID: "rev-2", AuthID: "a1"}
	blockBatchSave(t, r)
	res, err = r.RevokeAuthorization(req2)
	assertSaveFailureError(t, err)
	if res.AuthID != "" || res.Status != "" || res.Replayed || res.Err != nil {
		t.Fatalf("保存失败必须返回空结果: %+v", res)
	}
	if _, ok := r.state.Requests[requestKey("alice", "rev-2")]; ok {
		t.Fatal("未保存的拒绝不应占用请求号")
	}
	restoreBatchSave(t, r)
	res, err = r.RevokeAuthorization(req2)
	if !errors.Is(err, ErrAuthorizationUsed) || res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrAuthorizationUsed) {
		t.Fatalf("重提应在保存后返回 ErrAuthorizationUsed: %+v, %v", res, err)
	}

	// 失败保存的请求号不阻碍同号撤销另一份授权（不同参数 → 无冲突，因为未保存）。
	r2 := mustCreate(t, tempDir(t))
	authzWorld(t, r2)
	if _, err := r2.CreateAuthorization(createAuthReq(r2, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r2.CreateAuthorization(createAuthReq(r2, "a2", time.Hour)); err != nil {
		t.Fatal(err)
	}
	reqA := RevokeAuthorizationRequest{Operator: "mallory", Reason: "越权", RequestID: "same", AuthID: "a1"}
	if err := r2.RegisterAccount("mallory", "路人"); err != nil {
		t.Fatal(err)
	}
	blockBatchSave(t, r2)
	if _, err := r2.RevokeAuthorization(reqA); err == nil {
		t.Fatal("应返回保存错误")
	}
	restoreBatchSave(t, r2)
	// 同号但撤销另一份自己有权撤销的授权：不应报请求号冲突。
	reqB := RevokeAuthorizationRequest{Operator: "alice", Reason: "撤销", RequestID: "same", AuthID: "a2"}
	res, err = r2.RevokeAuthorization(reqB)
	if err != nil || res.Status != AuthRevoked {
		t.Fatalf("同号撤销另一份授权不应冲突: %+v, %v", res, err)
	}
}

